 it.each(['wiki','details'] as const)('copies a saved marker link into Edit after leaving the %s tab',async tab=>{const outline={kinds:[level('Article',0)]},article=node('Article','article','First.');article.content[0].references=[{logicalId:'marker',start:6,end:6,target:{type:'footnote',footnoteId:'a'}}];article.content.push({type:'text',logicalId:'a',format:'footnote',footnoteLabel:'a',text:'Note'});await mount(outline,[article],{initialTab:tab,wikiPanel:<div>Wiki panel</div>,detailsPanel:<div>Details panel</div>});window.history.replaceState(null,'','/editor?sessionId=session&versionId=source&tab='+tab+'&wikiStatus=saved&wikiHistoryPage=3&historyPage=2');const original=Object.getOwnPropertyDescriptor(navigator,'clipboard'),writeText=vi.fn().mockResolvedValue(undefined);Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText}});try{await click('Edit');await act(async()=>fireEvent.contextMenu(host.querySelector('#editor-ref-marker')!,{clientX:10,clientY:10}));await markerAction('Copy link to marker');expect(writeText).toHaveBeenCalledTimes(1);const target=new URL(writeText.mock.calls[0][0]);expect(target.searchParams.get('tab')).toBe('edit');expect(target.searchParams.get('selectedNode')).toBe('text-article');expect(target.searchParams.get('sessionId')).toBe('session');for(const key of ['wikiStatus','wikiHistoryPage','historyPage'])expect(target.searchParams.has(key)).toBe(false);expect(target.hash).toBe('#editor-ref-marker');}finally{if(original)Object.defineProperty(navigator,'clipboard',original);else Reflect.deleteProperty(navigator,'clipboard');}});
 it('places a new footnote after the end of a selection spanning two sentences',async()=>{const fixture=mixed();fixture.roots[0].content=[{type:'child',node:node('Sentence','first','First.')},{type:'child',node:node('Sentence','second','Second.')}];await mount(fixture.outline,fixture.roots,{scope:'sentence'});await act(async()=>{editors()[0].focus();const range=document.createRange();range.setStart(host.querySelector('[data-unit=first]')!.firstChild!,2);range.setEnd(host.querySelector('[data-unit=second]')!.firstChild!,4);const selection=document.getSelection()!;selection.removeAllRanges();selection.addRange(range);fireEvent(document,new Event('selectionchange'));await new Promise(resolve=>setTimeout(resolve,0));fireEvent.contextMenu(editors()[0],{clientX:10,clientY:10});});await markerAction('New footnote…');await paste(host.querySelector<HTMLElement>('[aria-label="Footnote text"]')!,'Annotation');await click('Insert marker and note');const final=nodes(result());expect(final.find(node=>node.logicalId==='first')!.content[0].references??[]).toEqual([]);expect(final.find(node=>node.logicalId==='second')!.content[0].references).toEqual([expect.objectContaining({start:4,end:4,target:expect.objectContaining({type:'footnote'})})]);});
 it('keeps the enlarged footnote editing surface stable when focus moves onto Apply',async()=>{const outline={kinds:[level('Article',0)]};await mount(outline,[node('Article','article','Body.')]);await act(async()=>editors()[0].focus());await click('Footnotes');await click('New footnote…');const note=host.querySelector<HTMLElement>('[aria-label="Footnote text"]')!;await paste(note,'A note retained while its marker moves.');expect(note.parentElement?.className).toContain('activeCanvas');await act(async()=>button('Insert marker and note').focus());expect(document.activeElement).toBe(button('Insert marker and note'));expect(note.parentElement?.className).toContain('activeCanvas');await click('Insert marker and note');expect(host.querySelector('[aria-label="Footnote text"]')).toBeNull();expect(result()[0].content.some(entry=>entry.format==='footnote')).toBe(true);});
 it.each(['inline','superscript'] as const)('retains a paragraph label with %s placement and never creates an unnamed heading button',async labelPlacement=>{const outline={kinds:[level('Article',0,'Paragraph'),level('Paragraph',1,'Sentence',{mayHoldText:true,showKind:false,showTitle:false,labelPlacement}),level('Sentence',2,undefined,{showKind:false,showLabel:false,showTitle:false})]},paragraph={...node('Paragraph','paragraph'),label:'(1)',content:[{type:'child' as const,node:node('Sentence','sentence','A sentence.')} ]},article={...node('Article','article'),label:'1',title:'Rights',content:[{type:'child' as const,node:paragraph}]};await mount(outline,[article]);expect(button('(1)').textContent).toBe('(1)');expect([...host.querySelectorAll('button')].filter(button=>!button.textContent?.trim()&&!button.getAttribute('aria-label'))).toEqual([]);const result=await axeRun(host,{runOnly:{type:'rule',values:['button-name']}});expect(result.violations).toEqual([]);});
 it('uses configured display labels and accessible controls with no repeated per-sentence forms',async()=>{const fixture=mixed();await mount(fixture.outline,fixture.roots);expect(host.querySelectorAll('textarea')).toHaveLength(0);expect(host.querySelectorAll('[data-editor-tools]')).toHaveLength(1);expect(button('Undo').disabled).toBe(true);expect(button('Redo').disabled).toBe(true);await click('Show sentence boundaries');expect(button('Show sentence boundaries').getAttribute('aria-pressed')).toBe('true');const result=await axeRun(host,{rules:{'color-contrast':{enabled:false}}});expect(result.violations.map(item=>item.id)).toEqual([]);});
